/// <reference lib="dom" />
// Generated by tools/prepare_admin_menu_image_vendor.py; only one WASM is bundled.
// @ts-types="./_vendor/index.d.ts"
import {
  ConfigurationFiles,
  initializeImageMagick,
  MagickFormat,
  MagickGeometry,
  MagickImage,
  MagickReadSettings,
  ResourceLimits,
} from "./_vendor/index.js";

const MAX_BYTES = 4 * 1024 * 1024;
const MAX_DIMENSION = 2048;
const MAX_PIXELS = 4_000_000;
const OUTPUT_DIMENSION = 1024;
const MAX_PROCESS_MS = 1400;

let initialization: Promise<void> | undefined;

function initialize(): Promise<void> {
  return initialization ??= initializeProcessor();
}

async function initializeProcessor(): Promise<void> {
  const configuration = ConfigurationFiles.default;
  configuration.policy.data = `<policymap>
  <policy domain="delegate" rights="none" pattern="*"/>
  <policy domain="filter" rights="none" pattern="*"/>
  <policy domain="coder" rights="none" pattern="*"/>
  <policy domain="coder" rights="read|write" pattern="{JPEG,PNG,WEBP}"/>
  <policy domain="path" rights="none" pattern="*"/>
  <policy domain="resource" name="width" value="2048"/>
  <policy domain="resource" name="height" value="2048"/>
  <policy domain="resource" name="area" value="4.1MP"/>
  <policy domain="resource" name="memory" value="64MiB"/>
  <policy domain="resource" name="disk" value="0"/>
  <policy domain="resource" name="list-length" value="2"/>
  <policy domain="system" name="max-memory-request" value="32MiB"/>
  <policy domain="system" name="max-profile-size" value="256KiB"/>
</policymap>`;
  const wasm = await Deno.readFile(
    new URL("./_vendor/magick.wasm", import.meta.url),
  );
  await initializeImageMagick(wasm, configuration);
  ResourceLimits.memory = 64n * 1024n * 1024n;
  ResourceLimits.disk = 0n;
  ResourceLimits.width = 2048n;
  ResourceLimits.height = 2048n;
  // ImageMagick treats the exact area boundary as cache spill; disk is denied.
  ResourceLimits.area = 4_000_001n;
  // Transformations need an internal scratch image; containers still deny
  // animation and multiple compressed image payloads before decoding.
  ResourceLimits.listLength = 2n;
  ResourceLimits.maxMemoryRequest = 32n * 1024n * 1024n;
  ResourceLimits.maxProfileSize = 256n * 1024n;
}

function fail(reason = "invalid_image"): never {
  throw new Error(reason);
}
function ascii(bytes: Uint8Array, start: number, count: number): string {
  return String.fromCharCode(...bytes.subarray(start, start + count));
}
function be32(bytes: Uint8Array, offset: number): number {
  return new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength)
    .getUint32(offset);
}
function le32(bytes: Uint8Array, offset: number): number {
  return new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength)
    .getUint32(offset, true);
}
function dimensions(width: number, height: number): void {
  if (
    !Number.isInteger(width) || !Number.isInteger(height) || width < 1 ||
    height < 1 ||
    width > MAX_DIMENSION || height > MAX_DIMENSION ||
    width * height > MAX_PIXELS
  ) fail("image_dimensions_exceeded");
}

// Container checks run before native decoding. Force the validated raster coder
// during decoding as well; neither a filename nor client MIME chooses a coder.
function preflight(
  bytes: Uint8Array,
  contentType: string,
): { format: MagickFormat; width: number; height: number } {
  if (bytes.length < 12 || bytes.length > MAX_BYTES) {
    fail("image_bytes_exceeded");
  }
  if (ascii(bytes, 0, 8) === "\x89PNG\r\n\x1a\n") {
    if (contentType !== "image/png") fail("image_type_mismatch");
    let offset = 8, width = 0, height = 0, hasData = false;
    while (offset + 12 <= bytes.length) {
      const length = be32(bytes, offset), type = ascii(bytes, offset + 4, 4);
      if (length > bytes.length - offset - 12) fail();
      if (offset === 8 && (type !== "IHDR" || length !== 13)) fail();
      if (type === "acTL" || type === "fcTL" || type === "fdAT") {
        fail("animated_image_not_supported");
      }
      if (type === "IHDR") {
        if (offset !== 8) fail();
        width = be32(bytes, offset + 8);
        height = be32(bytes, offset + 12);
        dimensions(width, height);
      }
      if (type === "IDAT") hasData = true;
      offset += length + 12;
      if (type === "IEND") {
        if (length !== 0 || !hasData || offset !== bytes.length) fail();
        return { format: MagickFormat.Png, width, height };
      }
    }
    fail();
  }
  if (ascii(bytes, 0, 4) === "RIFF" && ascii(bytes, 8, 4) === "WEBP") {
    if (contentType !== "image/webp") fail("image_type_mismatch");
    if (le32(bytes, 4) + 8 !== bytes.length) fail();
    let offset = 12, width = 0, height = 0, payloads = 0;
    while (offset + 8 <= bytes.length) {
      const type = ascii(bytes, offset, 4),
        length = le32(bytes, offset + 4),
        start = offset + 8;
      if (length > bytes.length - start) fail();
      if (type === "ANIM" || type === "ANMF") {
        fail("animated_image_not_supported");
      }
      if (type === "VP8X") {
        if (length !== 10 || offset !== 12) fail();
        if (bytes[start] & 0x02) fail("animated_image_not_supported");
        const w = 1 + bytes[start + 4] + bytes[start + 5] * 256 +
          bytes[start + 6] * 65536;
        const h = 1 + bytes[start + 7] + bytes[start + 8] * 256 +
          bytes[start + 9] * 65536;
        dimensions(w, h);
      }
      if (type === "VP8 ") {
        if (length < 10 || ascii(bytes, start + 3, 3) !== "\x9d\x01\x2a") {
          fail();
        }
        width = (bytes[start + 6] + bytes[start + 7] * 256) & 0x3fff;
        height = (bytes[start + 8] + bytes[start + 9] * 256) & 0x3fff;
        dimensions(width, height);
        payloads++;
      }
      if (type === "VP8L") {
        if (length < 5 || bytes[start] !== 0x2f) fail();
        const value = le32(bytes, start + 1);
        width = (value & 0x3fff) + 1;
        height = ((value >>> 14) & 0x3fff) + 1;
        dimensions(width, height);
        payloads++;
      }
      offset = start + length + (length & 1);
    }
    if (offset !== bytes.length || payloads !== 1) fail();
    return { format: MagickFormat.WebP, width, height };
  }
  if (bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff) {
    if (contentType !== "image/jpeg") fail("image_type_mismatch");
    let offset = 2, width = 0, height = 0, hasScan = false;
    while (offset + 2 <= bytes.length) {
      if (bytes[offset++] !== 0xff) fail();
      while (bytes[offset] === 0xff) offset++;
      const marker = bytes[offset++];
      if (marker === 0xd9) {
        if (!width || !height || !hasScan || offset !== bytes.length) fail();
        return { format: MagickFormat.Jpeg, width, height };
      }
      if (marker === 0xd8 || marker === 0 || offset + 2 > bytes.length) fail();
      const length = bytes[offset] * 256 + bytes[offset + 1];
      if (length < 2 || length > bytes.length - offset) fail();
      if (marker === 0xe2 && ascii(bytes, offset + 2, 4) === "MPF\0") {
        fail("animated_image_not_supported");
      }
      if ([0xc0, 0xc1, 0xc2].includes(marker)) {
        if (length < 8 || width || height) fail();
        height = bytes[offset + 3] * 256 + bytes[offset + 4];
        width = bytes[offset + 5] * 256 + bytes[offset + 6];
        dimensions(width, height);
      }
      offset += length;
      if (marker === 0xda) {
        hasScan = true;
        // Consume entropy data, honoring byte stuffing and restart markers.
        // Return structural markers to the outer parser for progressive JPEGs.
        while (offset < bytes.length) {
          if (bytes[offset++] !== 0xff) continue;
          const markerStart = offset - 1;
          while (bytes[offset] === 0xff) offset++;
          const next = bytes[offset++];
          if (next === 0 || (next >= 0xd0 && next <= 0xd7)) continue;
          offset = markerStart;
          break;
        }
      }
    }
    fail();
  }
  fail("unsupported_image_type");
}

export async function normalizeMenuImage(
  bytes: Uint8Array,
  contentType: string,
): Promise<Uint8Array> {
  // Reject unsupported/oversized containers without reading or initializing WASM.
  const checked = preflight(bytes, contentType);
  await initialize();
  // ImageMagick operations below are synchronous. No request can interleave
  // mutation of a decoder/image while the CPU work is running.
  const start = performance.now();
  const image = MagickImage.create();
  let warning = false;
  image.onWarning = () => {
    warning = true;
  };
  image.onProgress = (event) => {
    if (performance.now() - start > MAX_PROCESS_MS) event.cancel = true;
  };
  try {
    image.read(bytes, new MagickReadSettings({ format: checked.format }));
    if (warning) fail("corrupt_image");
    dimensions(image.width, image.height);
    if (image.width !== checked.width || image.height !== checked.height) {
      fail();
    }
    image.autoOrient();
    const geometry = new MagickGeometry(OUTPUT_DIMENSION, OUTPUT_DIMENSION);
    geometry.greater = true;
    image.resize(geometry);
    image.strip();
    image.quality = 80;
    image.settings.setDefine(MagickFormat.WebP, "lossless", false);
    image.settings.setDefine(MagickFormat.WebP, "method", 0);
    const output = image.write(MagickFormat.WebP, (data) => data.slice());
    if (warning || performance.now() - start > MAX_PROCESS_MS) {
      fail("image_processing_timeout");
    }
    if (output.length === 0 || output.length > MAX_BYTES) {
      fail("image_bytes_exceeded");
    }
    return output;
  } finally {
    image.dispose();
  }
}
